    CREATE TABLE IF NOT EXISTS accounts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        platform TEXT,
        username TEXT,
        password TEXT,
        status TEXT DEFAULT 'active',
        used_today INTEGER DEFAULT 0
    );
&quot;);

// إنشاء مستخدم افتراضي
$admin = $db-&gt;query(&quot;SELECT * FROM users WHERE username='admin'&quot;)-&gt;fetch();
if(!$admin) {
    $hash = password_hash('admin123', PASSWORD_DEFAULT);
    $db-&gt;prepare(&quot;INSERT INTO users (username, password, balance) VALUES (?, ?, ?)&quot;)-&gt;execute(['admin', $hash, 1000]);
}

// ============================================================
// دوال الرشق (داخل الموقع نفسه)
// ============================================================

function getAvailableAccount($platform) {
    global $db;
    $stmt = $db-&gt;prepare(&quot;SELECT * FROM accounts WHERE platform = ? AND status = 'active' AND used_today &lt; 50 ORDER BY used_today LIMIT 1&quot;);
    $stmt-&gt;execute([$platform]);
    return $stmt-&gt;fetch();
}

function updateAccountUsage($account_id) {
    global $db;
    $db-&gt;prepare(&quot;UPDATE accounts SET used_today = used_today + 1 WHERE id = ?&quot;)-&gt;execute([$account_id]);
}

function performRaid($platform, $target, $type, $quantity) {
    global $db;

    $results = ['success' =&gt; 0, 'failed' =&gt; 0];

    for($i = 0; $i &lt; min($quantity, 200); $i++) {
        $account = getAvailableAccount($platform);

        if(!$account) {
            $results['failed']++;
            continue;
        }

        // هنا يتم استخدام الحساب لمتابعة/إعجاب/مشاهدة
        $result = useAccount($account, $platform, $target, $type);

        if($result) {
            $results['success']++;
            updateAccountUsage($account['id']);
        } else {
            $results['failed']++;
        }

        // تأخير بين العمليات
        usleep(rand(500000, 2000000)); // 0.5-2 ثواني
    }

    return $results;
}

function useAccount($account, $platform, $target, $type) {
    // محاكاة استخدام الحساب
    // في الحقيقة تحتاج إلى متصفحات وسيلينيوم
    return rand(1, 100) &gt; 30; // 70% نجاح للتجربة
}

// ============================================================
